import{_ as p,a0 as a,w as i,s as S,I as t,x as s,a1 as o,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const N=JSON.parse('{"title":"如何通过反向 SSH 隧道访问 NAT 后面的 Linux 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何通过反向 SSH 隧道访问 NAT 后面的 Linux 服务器 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何通过反向 SSH 隧道访问 NAT 后面的 Linux 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何通过反向 SSH 隧道访问 NAT 后面的 Linux 服务器 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150504 How to access a Linux server behind NAT via reverse SSH tunnel","title":"如何通过反向 SSH 隧道访问 NAT 后面的 Linux 服务器","tag":"201508","desc":""},"relativePath":"201508/20150504 How to access a Linux server behind NAT via reverse SSH tunnel.md","filePath":"[post].md"}'),d={name:"201508/20150504 How to access a Linux server behind NAT via reverse SSH tunnel.md"};function u(h,e,H,m,x,T){const r=a("Link");return i(),S("div",null,[e[24]||(e[24]=t("h1",{id:"如何通过反向-ssh-隧道访问-nat-后面的-linux-服务器",tabindex:"-1"},[s("如何通过反向 SSH 隧道访问 NAT 后面的 Linux 服务器 "),t("a",{class:"header-anchor",href:"#如何通过反向-ssh-隧道访问-nat-后面的-linux-服务器","aria-label":"Permalink to “如何通过反向 SSH 隧道访问 NAT 后面的 Linux 服务器”"},"​")],-1)),e[25]||(e[25]=t("p",null,"你在家里运行着一台 Linux 服务器，它放在一个 NAT 路由器或者限制性防火墙后面。现在你想在外出时用 SSH 登录到这台服务器。你如何才能做到呢？SSH 端口转发当然是一种选择。但是，如果你需要处理多级嵌套的 NAT 环境，端口转发可能会变得非常棘手。另外，在多种 ISP 特定条件下可能会受到干扰，例如阻塞转发端口的限制性 ISP 防火墙、或者在用户间共享 IPv4 地址的运营商级 NAT。",-1)),e[26]||(e[26]=t("h3",{id:"什么是反向-ssh-隧道",tabindex:"-1"},[s("什么是反向 SSH 隧道？ "),t("a",{class:"header-anchor",href:"#什么是反向-ssh-隧道","aria-label":"Permalink to “什么是反向 SSH 隧道？”"},"​")],-1)),t("p",null,[e[1]||(e[1]=s("SSH 端口转发的一种替代方案是 ",-1)),e[2]||(e[2]=t("strong",null,"反向 SSH 隧道",-1)),e[3]||(e[3]=s("。反向 SSH 隧道的概念非常简单。使用这种方案，在你的受限的家庭网络之外你需要另一台主机（所谓的“中继主机”），你能从当前所在地通过 SSH 登录到它。你可以用有公网 IP 地址的 ",-1)),o(r,{href:"http://xmodulo.com/go/digitalocean"},{default:n(()=>[...e[0]||(e[0]=[s("VPS 实例",-1)])]),_:1}),e[4]||(e[4]=s(" 配置一个中继主机。然后要做的就是从你的家庭网络服务器中建立一个到公网中继主机的永久 SSH 隧道。有了这个隧道，你就可以从中继主机中连接“回”家庭服务器（这就是为什么称之为 “反向” 隧道）。不管你在哪里、你的家庭网络中的 NAT 或 防火墙限制多么严格，只要你可以访问中继主机，你就可以连接到家庭服务器。",-1))]),e[27]||(e[27]=l(`<p><img src="https://farm8.staticflickr.com/7742/17162647378_c7d9f10de8_b.jpg" alt=""></p><h3 id="在-linux-上设置反向-ssh-隧道" tabindex="-1">在 Linux 上设置反向 SSH 隧道 <a class="header-anchor" href="#在-linux-上设置反向-ssh-隧道" aria-label="Permalink to “在 Linux 上设置反向 SSH 隧道”">​</a></h3><p>让我们来看看怎样创建和使用反向 SSH 隧道。我们做如下假设：我们会设置一个从家庭服务器（homeserver）到中继服务器（relayserver）的反向 SSH 隧道，然后我们可以通过中继服务器从客户端计算机（clientcomputer） SSH 登录到家庭服务器。本例中的<strong>中继服务器</strong> 的公网 IP 地址是 1.1.1.1。</p><p>在家庭服务器上，按照以下方式打开一个到中继服务器的 SSH 连接。</p><pre><code>homeserver~$ ssh -fN -R 10022:localhost:22 relayserver_user@1.1.1.1
</code></pre><p>这里端口 10022 是任何你可以使用的端口数字。只需要确保中继服务器上不会有其它程序使用这个端口。</p><p>“-R 10022:localhost:22” 选项定义了一个反向隧道。它转发中继服务器 10022 端口的流量到家庭服务器的 22 号端口。</p><p>用 “-fN” 选项，当你成功通过 SSH 服务器验证时 SSH 会进入后台运行。当你不想在远程 SSH 服务器执行任何命令，就像我们的例子中只想转发端口的时候非常有用。</p><p>运行上面的命令之后，你就会回到家庭主机的命令行提示框中。</p><p>登录到中继服务器，确认其 127.0.0.1:10022 绑定到了 sshd。如果是的话就表示已经正确设置了反向隧道。</p><pre><code>relayserver~$ sudo netstat -nap | grep 10022
</code></pre><hr><pre><code>tcp      0    0 127.0.0.1:10022          0.0.0.0:*               LISTEN      8493/sshd           
</code></pre><p>现在就可以从任何其它计算机（客户端计算机）登录到中继服务器，然后按照下面的方法访问家庭服务器。</p><pre><code>relayserver~$ ssh -p 10022 homeserver_user@localhost
</code></pre><p>需要注意的一点是你在上面为localhost输入的 SSH 登录/密码应该是家庭服务器的，而不是中继服务器的，因为你是通过隧道的本地端点登录到家庭服务器，因此不要错误输入中继服务器的登录/密码。成功登录后，你就在家庭服务器上了。</p><h3 id="通过反向-ssh-隧道直接连接到网络地址变换后的服务器" tabindex="-1">通过反向 SSH 隧道直接连接到网络地址变换后的服务器 <a class="header-anchor" href="#通过反向-ssh-隧道直接连接到网络地址变换后的服务器" aria-label="Permalink to “通过反向 SSH 隧道直接连接到网络地址变换后的服务器”">​</a></h3><p>上面的方法允许你访问 NAT 后面的 <strong>家庭服务器</strong>，但你需要登录两次：首先登录到 <strong>中继服务器</strong>，然后再登录到<strong>家庭服务器</strong>。这是因为中继服务器上 SSH 隧道的端点绑定到了回环地址（127.0.0.1）。</p><p>事实上，有一种方法可以只需要登录到中继服务器就能直接访问NAT之后的家庭服务器。要做到这点，你需要让中继服务器上的 sshd 不仅转发回环地址上的端口，还要转发外部主机的端口。这通过指定中继服务器上运行的 sshd 的 <strong>GatewayPorts</strong> 实现。</p><p>打开<strong>中继服务器</strong>的 /etc/ssh/sshd_conf 并添加下面的行。</p><pre><code>relayserver~$ vi /etc/ssh/sshd_conf
</code></pre><hr><pre><code>GatewayPorts clientspecified
</code></pre><p>重启 sshd。</p><p>基于 Debian 的系统：</p><pre><code>relayserver~$ sudo /etc/init.d/ssh restart
</code></pre><p>基于红帽的系统：</p><pre><code>relayserver~$ sudo systemctl restart sshd
</code></pre><p>现在在家庭服务器中按照下面方式初始化一个反向 SSH 隧道。</p><pre><code>homeserver~$ ssh -fN -R 1.1.1.1:10022:localhost:22 relayserver_user@1.1.1.1
</code></pre><p>登录到中继服务器然后用 netstat 命令确认成功建立的一个反向 SSH 隧道。</p><pre><code>relayserver~$ sudo netstat -nap | grep 10022
</code></pre><hr><pre><code>tcp      0      0 1.1.1.1:10022     0.0.0.0:*           LISTEN      1538/sshd: dev  
</code></pre><p>不像之前的情况，现在隧道的端点是 1.1.1.1:10022（中继服务器的公网 IP 地址），而不是 127.0.0.1:10022。这就意味着从外部主机可以访问隧道的另一端。</p><p>现在在任何其它计算机（客户端计算机），输入以下命令访问网络地址变换之后的家庭服务器。</p><pre><code>clientcomputer~$ ssh -p 10022 homeserver_user@1.1.1.1
</code></pre><p>在上面的命令中，1.1.1.1 是中继服务器的公共 IP 地址，homeserver_user必须是家庭服务器上的用户账户。这是因为你真正登录到的主机是家庭服务器，而不是中继服务器。后者只是中继你的 SSH 流量到家庭服务器。</p><h3 id="在-linux-上设置一个永久反向-ssh-隧道" tabindex="-1">在 Linux 上设置一个永久反向 SSH 隧道 <a class="header-anchor" href="#在-linux-上设置一个永久反向-ssh-隧道" aria-label="Permalink to “在 Linux 上设置一个永久反向 SSH 隧道”">​</a></h3><p>现在你已经明白了怎样创建一个反向 SSH 隧道，然后把隧道设置为 “永久”，这样隧道启动后就会一直运行（不管临时的网络拥塞、SSH 超时、中继主机重启，等等）。毕竟，如果隧道不是一直有效，你就不能可靠的登录到你的家庭服务器。</p><p>对于永久隧道，我打算使用一个叫 autossh 的工具。正如名字暗示的，这个程序可以让你的 SSH 会话无论因为什么原因中断都会自动重连。因此对于保持一个反向 SSH 隧道非常有用。</p>`,41)),t("p",null,[e[6]||(e[6]=s("第一步，我们要设置从家庭服务器到中继服务器的",-1)),o(r,{href:"https://linux.cn/article-5444-1.html"},{default:n(()=>[...e[5]||(e[5]=[s("无密码 SSH 登录",-1)])]),_:1}),e[7]||(e[7]=s("。这样的话，autossh 可以不需要用户干预就能重启一个损坏的反向 SSH 隧道。",-1))]),t("p",null,[e[9]||(e[9]=s("下一步，在建立隧道的家庭服务器上",-1)),o(r,{href:"https://linux.cn/article-5459-1.html"},{default:n(()=>[...e[8]||(e[8]=[s("安装 autossh",-1)])]),_:1}),e[10]||(e[10]=s("。",-1))]),e[28]||(e[28]=l(`<p>在家庭服务器上，用下面的参数运行 autossh 来创建一个连接到中继服务器的永久 SSH 隧道。</p><pre><code>homeserver~$ autossh -M 10900 -fN -o &quot;PubkeyAuthentication=yes&quot; -o &quot;StrictHostKeyChecking=false&quot; -o &quot;PasswordAuthentication=no&quot; -o &quot;ServerAliveInterval 60&quot; -o &quot;ServerAliveCountMax 3&quot; -R 1.1.1.1:10022:localhost:22 relayserver_user@1.1.1.1
</code></pre><p>“-M 10900” 选项指定中继服务器上的监视端口，用于交换监视 SSH 会话的测试数据。中继服务器上的其它程序不能使用这个端口。</p><p>“-fN” 选项传递给 ssh 命令，让 SSH 隧道在后台运行。</p><p>“-o XXXX” 选项让 ssh：</p><ul><li>使用密钥验证，而不是密码验证。</li><li>自动接受（未知）SSH 主机密钥。</li><li>每 60 秒交换 keep-alive 消息。</li><li>没有收到任何响应时最多发送 3 条 keep-alive 消息。</li></ul><p>其余 SSH 隧道相关的选项和之前介绍的一样。</p><p>如果你想系统启动时自动运行 SSH 隧道，你可以将上面的 autossh 命令添加到 /etc/rc.local。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在这篇博文中，我介绍了你如何能从外部通过反向 SSH 隧道访问限制性防火墙或 NAT 网关之后的 Linux 服务器。这里我介绍了家庭网络中的一个使用事例，但在企业网络中使用时你尤其要小心。这样的一个隧道可能被视为违反公司政策，因为它绕过了企业的防火墙并把企业网络暴露给外部攻击。这很可能被误用或者滥用。因此在使用之前一定要记住它的作用。</p><hr>`,11)),t("p",null,[e[12]||(e[12]=s("via: ",-1)),o(r,{href:"http://xmodulo.com/access-linux-server-behind-nat-reverse-ssh-tunnel.html"},{default:n(()=>[...e[11]||(e[11]=[s("http://xmodulo.com/access-linux-server-behind-nat-reverse-ssh-tunnel.html",-1)])]),_:1})]),t("p",null,[e[16]||(e[16]=s("作者：",-1)),o(r,{href:"http://xmodulo.com/author/nanni"},{default:n(()=>[...e[13]||(e[13]=[s("Dan Nanni",-1)])]),_:1}),e[17]||(e[17]=s(" 译者：",-1)),o(r,{href:"https://github.com/ictlyh"},{default:n(()=>[...e[14]||(e[14]=[s("ictlyh",-1)])]),_:1}),e[18]||(e[18]=s(" 校对：",-1)),o(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[15]||(e[15]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[21]||(e[21]=s("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[19]||(e[19]=[s("LCTT",-1)])]),_:1}),e[22]||(e[22]=s(" 原创翻译，",-1)),o(r,{href:"http://linux.cn/"},{default:n(()=>[...e[20]||(e[20]=[s("Linux中国",-1)])]),_:1}),e[23]||(e[23]=s(" 荣誉推出",-1))])])}const A=p(d,[["render",u]]);export{N as __pageData,A as default};
